#!/usr/bin/env python3
"""Optional content generator. Python 3.9+; standard library only.
The generated HTML is already included and can be published without running this.
"""
from pathlib import Path
from html import escape
from datetime import date, timedelta
import json

ROOT = Path(__file__).resolve().parent
D = json.loads((ROOT / 'data/program.json').read_text())
PROJECTS = json.loads((ROOT / 'data/projects.json').read_text())
MENTORS = {m['id']: m for m in D['mentors']}
THRUSTS = {
 'security': {'number':'01', 'name':'Secure communications', 'verb':'Communicate securely.', 'lead':'Daniel Alabi', 'description':'Explore finite-key cryptography, authentication, and the limits of location-based security.'},
 'coding': {'number':'02', 'name':'Quantum coding', 'verb':'Protect fragile information.', 'lead':'Olgica Milenkovic', 'description':'Find out how codes and decoders perform when quantum noise is biased, correlated, or imperfectly modeled.'},
 'consensus': {'number':'03', 'name':'Distributed consensus', 'verb':'Coordinate across a network.', 'lead':'Eric Chitambar', 'description':'Investigate how local quantum operations can produce shared computations and common states.'}
}
def e(value): return escape(str(value), quote=True)
def tag(text, kind=''): return f'<span class="tag {kind}">{e(text)}</span>'
def arrow(): return '<span aria-hidden="true">↗</span>'
def link(url, text, cls='text-link'): return f'<a class="{cls}" href="{e(url)}">{e(text)} {arrow()}</a>'
def label(text): return f'<p class="eyebrow">{e(text)}</p>'
def intro(kicker, title, description):
 return f'<section class="page-intro container">{label(kicker)}<h1>{title}</h1><p class="lede">{description}</p></section>'
def callout(prefix=''):
 return f'''<section class="cta container"><div>{label('Your next research question starts here')}<h2>Bring your curiosity.<br>Build something that matters.</h2><p>No prior quantum coursework required. A summer of research, mentorship, and discovery at Illinois.</p></div>{link(prefix+'apply.html', 'Plan your summer', 'button button-light')}</section>'''
def page(filename, title, description, content, active='', prefix=''):
 nav = ''.join(f'<a href="{prefix}{file}"'+(' aria-current="page"' if key == active else '')+f'>{text}</a>' for key,file,text in [('projects','projects.html','Research'),('experience','experience.html','Experience'),('people','people.html','People'),('partners','partners.html','Partners')])
 fulltitle = f'{title} | Quantum REU 2027 · Illinois'
 html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{e(fulltitle)}</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#132b40">
<meta property="og:title" content="{e(fulltitle)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website">
<link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/site.js" defer></script>
</head><body><a class="skip-link" href="#main">Skip to content</a>
<div class="institution-strip"><div class="container"><span>UNIVERSITY OF ILLINOIS URBANA-CHAMPAIGN</span><span>SUMMER RESEARCH · {D['year']}</span></div></div>
<header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix}index.html" aria-label="Quantum REU home"><img src="{prefix}assets/favicon.svg" alt="" width="38" height="38"><span>Quantum <b>REU</b><small>Secure & reliable networks</small></span></a>
<button class="menu-toggle" aria-expanded="false" aria-controls="primary-nav" hidden>Menu <span aria-hidden="true">☰</span></button><nav id="primary-nav" aria-label="Main navigation">{nav}<a class="nav-cta" href="{prefix}apply.html"{' aria-current="page"' if active=='apply' else ''}>Summer 2027 <span aria-hidden="true">↗</span></a></nav></div></header>
<main id="main" tabindex="-1">{content}</main>
<footer class="site-footer"><div class="container"><div class="footer-top"><div><a class="footer-brand" href="{prefix}index.html">Quantum REU <span>2027</span></a><p>Secure and Reliable<br>Quantum Information Networks</p></div><div><strong>Explore</strong><a href="{prefix}projects.html">Research projects</a><a href="{prefix}experience.html">The summer experience</a><a href="{prefix}people.html">Investigators & mentors</a></div><div><strong>Connect</strong><a href="mailto:{e(D['contact_email'])}">{e(D['contact_name'])}</a><a href="mailto:{e(D['pi_email'])}">Contact the PI</a><a href="{prefix}apply.html#faq">Frequently asked questions</a></div></div><div class="footer-bottom"><p>{e(D['funding_statement'])}</p><p>{e(D['location'])}<br>{e(D['dates'])} · {D['students']} students · {D['weeks']} weeks</p></div></div></footer></body></html>'''
 path = ROOT / filename
 path.parent.mkdir(parents=True, exist_ok=True)
 path.write_text(html, encoding='utf-8')

def project_card(p, prefix=''):
 t=THRUSTS[p['thrust']]
 return f'''<article class="project-card {p['thrust']}" data-project data-thrust="{p['thrust']}"><div class="card-meta"><span class="project-id">{p['id']}</span><span>{e(t['name'])}</span></div><h3><a href="{prefix}projects/{p['slug']}.html">{e(p['short_title'])}</a></h3><p>{e(p['summary'])}</p><div class="card-methods">{e(' / '.join(p['methods'][:2]))}</div><a class="card-link" href="{prefix}projects/{p['slug']}.html">Explore project <span class="sr-only">{p['id']}</span>{arrow()}</a></article>'''

home = f'''<section class="hero container"><div class="hero-copy">{label('Research Experiences for Undergraduates · Summer 2027')}<h1>Secure and reliable<br><em>quantum</em><br>information networks.</h1><p class="hero-dates">{e(D["dates"])} · {D["weeks"]} weeks at Illinois</p><p class="lede">A summer to ask new questions at the intersection of quantum information, security, and computation.</p><div class="hero-actions">{link('projects.html','Explore the research','button')}{link('experience.html','Your 10-week experience')}</div><p class="hero-note"><span class="status-dot"></span>10 students. Three research thrusts. One connected community.</p></div><figure class="hero-visual"><img src="assets/network.svg" width="520" height="520" alt="Conceptual quantum network connecting three research areas: secure communications, quantum coding, and distributed consensus."><figcaption><span>THE RESEARCH QUESTION</span>How do we communicate, protect, and coordinate quantum information?</figcaption></figure></section>
<div class="fact-band"><dl class="container facts"><div><dt>When</dt><dd>{e(D['dates'])}</dd></div><div><dt>The cohort</dt><dd>{D['students']} undergraduate researchers</dd></div><div><dt>Where</dt><dd>Illinois Urbana-Champaign</dd></div><div><dt>Your starting point</dt><dd>Curiosity. No quantum course required.</dd></div></dl></div>
<section class="container section"><div class="section-heading"><div>{label('Three thrusts. Real research questions.')}<h2>The next network<br>starts with your ideas.</h2></div><p>Quantum information is fragile. Networks can be noisy. Trust is never automatic. Work with faculty to turn these challenges into a focused, original research project.</p></div><div class="thrust-grid">'''
for key,t in THRUSTS.items():
 home += f'''<a class="thrust-card {key}" href="projects.html?thrust={key}"><span class="eyebrow">THRUST {t['number']}</span><div class="thrust-icon" aria-hidden="true">{'⌁' if key=='security' else '⊞' if key=='coding' else '⋈'}</div><h3>{e(t['verb'])}</h3><p>{e(t['description'])}</p><span class="text-link">{e(t['name'])} {arrow()}</span></a>'''
home += f'''</div></section><section class="feature-section"><div class="container section"><div class="section-heading"><div>{label('A closer look')}<h2>Small systems.<br>Open questions.</h2></div>{link('projects.html','See all nine projects')}</div><div class="project-grid">{''.join(project_card(PROJECTS[i]) for i in [2,3,7])}</div></div></section>
<section class="container section community"><div>{label('You belong in the conversation')}<h2>You don’t need to arrive<br>as a quantum expert.</h2><p class="lede">Bring a foundation in programming, mathematics, physics, or engineering. We’ll build the shared language together.</p>{link('experience.html','Discover the summer experience')}</div><div class="community-list"><div><span>01</span><div><h3>Start with support</h3><p>Pre-arrival bridge modules and a quantum bootcamp help you move from your background into a research question.</p></div></div><div><span>02</span><div><h3>Find your research voice</h3><p>Faculty and near-peer mentoring connect you to weekly feedback, cross-thrust conversations, and a community of researchers.</p></div></div><div><span>03</span><div><h3>Leave with work you can share</h3><p>Develop a poster, a talk, a short technical paper, and reproducible code or a derivation notebook.</p></div></div></div></section>
<section class="partner-band"><div class="container"><p class="eyebrow">A connected research environment</p><div class="partner-names"><span>Illinois <b>ECE</b></span><span>IQUIST</span><span>IBM <b>Quantum</b></span><span>Chicago Quantum<br><b>Exchange</b></span></div><p>Campus resources and planned partner activities connect research to the wider quantum community. {link('partners.html','Explore the partners')}</p></div></section>{callout()}'''
home = home.replace('<div class="fact-band">', '<div class="opening-banner"><div class="container"><strong>Applications open December 1, 2026</strong><span>$700/week stipend · Housing &amp; travel covered</span><a href="apply.html">Participation details ↗</a></div></div><div class="fact-band">')
page('index.html',D['title'],'A 10-week undergraduate research program at Illinois, May 24–July 30, 2027. Ten students explore quantum security, coding, and distributed consensus.',home)

projects = intro('The research · Nine project directions','Find a question<br>you want to follow.','Explore three connected thrusts in secure and reliable quantum networks. Each project offers a concrete starting point, room for discovery, and a path to a result you can explain.')
projects += '''<section class="container project-browser" aria-labelledby="catalog-heading"><h2 class="sr-only" id="catalog-heading">Project catalog</h2><div class="project-controls" hidden><div class="filter-buttons" role="group" aria-label="Filter by research thrust"><button type="button" data-filter="all" aria-pressed="true">All projects <span>09</span></button><button type="button" data-filter="security" aria-pressed="false">Secure communications</button><button type="button" data-filter="coding" aria-pressed="false">Quantum coding</button><button type="button" data-filter="consensus" aria-pressed="false">Distributed consensus</button></div><div class="search-row"><label for="project-search">Search projects</label><input id="project-search" type="search" placeholder="Try Qiskit, noise, graphs…" autocomplete="off"><p id="result-count" role="status" aria-live="polite">9 projects</p></div></div><div class="project-grid">'''+''.join(project_card(p) for p in PROJECTS)+'''</div><div id="empty-results" class="empty-state" hidden><h3>No matching projects</h3><p>Try another search or select a different thrust.</p><button type="button" class="button" id="reset-search">Reset filters</button></div></section>'''
projects += '''<section class="container section matching"><div>'''+label('How projects are matched')+'''<h2>A direction to start.<br>A question to make your own.</h2></div><div><p>You’ll indicate your research interests and preferred thrusts. Matching considers your preparation, interests, available mentoring, and cohort balance. Final scope is developed with your mentor.</p><p>These are research directions, not a promise that every listed project will be assigned. A good outcome may be a new calculation, a benchmark, a protocol comparison, or a carefully explained negative result.</p><p class="small">Suggested preparation on each page is guidance, not an extra eligibility requirement.</p></div></section>'''+callout()
page('projects.html','Research projects','Explore all nine projects in quantum security, quantum coding, and distributed quantum consensus.',projects,'projects')

for p in PROJECTS:
 t=THRUSTS[p['thrust']]
 mentors=''.join(f'<a class="mentor-mini" href="../people.html#{m}"><span class="initials">{MENTORS[m]["initials"]}</span><span><strong>{e(MENTORS[m]["name"])}</strong><small>{e(MENTORS[m]["role"])}</small></span></a>' for m in p['mentors'])
 other=[q for q in PROJECTS if q['thrust']==p['thrust'] and q['id']!=p['id']]
 body=f'''<div class="container breadcrumb"><a href="../projects.html">Research</a><span aria-hidden="true">/</span><a href="../projects.html?thrust={p['thrust']}">{e(t['name'])}</a><span aria-hidden="true">/</span><span>{p['id']}</span></div><section class="container project-intro {p['thrust']}">{label('Project '+p['id']+' · Thrust '+t['number'])}<h1>{e(p['title'])}</h1><p class="lede">{e(p['summary'])}</p><div class="tags">{''.join(tag(x) for x in p['methods'])}</div></section><div class="container project-layout"><article class="project-story"><section class="question-box">{label('The question')}<h2>{e(p['question'])}</h2></section><section><h2>Why it matters</h2><p>{e(p['context'])}</p></section><section><h2>What you could investigate</h2><ol class="research-steps">{''.join('<li>'+e(x)+'</li>' for x in p['work'])}</ol></section><section><h2>What you could create</h2><ul class="outcome-list">{''.join('<li>'+e(x)+'</li>' for x in p['outcomes'])}</ul></section>{'<p class="editorial-note">'+e(p['note'])+'</p>' if p.get('note') else ''}</article><aside class="project-sidebar"><section><h2>Faculty connection</h2>{mentors}<p class="small">Based on the proposed thrust and mentoring roles. Final assignments are made through project matching.</p></section><section><h2>A useful starting point</h2><p>{e(p['entry'])}</p><p class="small">No prior quantum coursework is required for the program.</p></section><section><h2>A summer of research</h2><p>{e(D['dates'])}<br>{e(D['location'])}</p>{link('../apply.html','Participation details','button')}</section></aside></div><section class="container section"><div class="section-heading"><div>{label('Keep exploring')}<h2>More in {e(t['name'].lower())}.</h2></div>{link('../projects.html','All research projects')}</div><div class="project-grid two">{''.join(project_card(q,'../') for q in other)}</div></section>'''
 page('projects/'+p['slug']+'.html',p['id']+' · '+p['short_title'],p['summary'],body,'projects','../')

experience=intro('May 24–July 30, 2027 · Illinois Urbana-Champaign','Ten weeks.<br>A new way to think.','Move from shared foundations to a research contribution of your own, supported by faculty mentors, near-peer researchers, and a cohort working across disciplines.')
experience+='''<section class="container experience-overview"><div class="big-number"><strong>10</strong><span>weeks of discovery</span></div><div><h2>A residential research experience</h2><p>The program is based in Electrical and Computer Engineering at the University of Illinois Urbana-Champaign, with connections to IQUIST, the Coordinated Science Laboratory, and campus computing resources.</p><p>The work emphasizes theory, algorithms, and reproducible computation. You can contribute through simulations, mathematical reasoning, visualization, or protocol analysis; specialized quantum hardware is not required for every project.</p></div></section><section class="container section"><div class="section-heading"><div>'''+label('Your research pathway')+'''<h2>From a first question<br>to a defensible result.</h2></div><p>The schedule below describes the planned research progression. Detailed daily schedules and partner activities will be shared with participants.</p></div><ol class="timeline">'''
stages=[('Before arrival','Build the foundations','Short bridge modules in Python/NumPy, complex vectors, probability, and scientific notebooks; a mentor introduction and software setup.'),('Week 1','Meet your research community','Orientation, responsible research, quantum-network bootcamp, computing safety, and exploration of project directions.'),('Week 2','Make the question your own','Map the literature, create a project charter and reproducibility plan, and develop a mentoring compact and Individual Development Plan.'),('Weeks 3–4','Reproduce, explain, then vary','Replicate a known result, begin guided implementation or derivation, and test the assumptions behind your first research direction.'),('Week 5','Pause, present, and refine','Give a midpoint talk and write a short memo. Use mentor and peer feedback to calibrate the scope and the next experiments.'),('Weeks 6–7','Work with greater independence','Test hypotheses, compare protocols, debug models, or develop proofs, alongside career and graduate-school programming.'),('Weeks 8–9','Check the evidence. Tell the story.','Complete robustness checks and peer reproduction, then develop your paper, poster, and accessible research explanation.'),('Week 10','Share what you discovered','Present at the final symposium, submit your research package, and create a continuation plan with your mentor.'),('After the summer','Keep the connection','The mentoring plan includes follow-ups approximately six weeks and four months after the program, with next steps tailored to your project and goals.')]
experience+=''.join(f'<li><span class="timeline-period">{period}</span><div><h3>{title}</h3><p>{desc}</p></div></li>' for period,title,desc in stages)
experience+='''</ol></section><section class="feature-section"><div class="container section"><div class="section-heading"><div>'''+label('The weekly rhythm')+'''<h2>Research is a conversation.</h2></div><p>Support is designed to evolve as your confidence and independence grow.</p></div><div class="info-grid"><article><span class="eyebrow">MENTORSHIP</span><h3>Guidance you can count on</h3><p>Weekly faculty meetings, frequent near-peer support, and feedback at key project milestones.</p></article><article><span class="eyebrow">COMMUNITY</span><h3>Ideas across the thrusts</h3><p>Cohort stand-ups, seminars, and peer circles connect security, coding, and consensus.</p></article><article><span class="eyebrow">YOUR FUTURE</span><h3>A view beyond the project</h3><p>Responsible research, career conversations, graduate-school preparation, and planned quantum-industry engagement.</p></article></div></div></section><section class="container section matching"><div>'''+label('Your research portfolio')+'''<h2>Leave with a result<br>you can stand behind.</h2></div><div><ul class="outcome-list"><li>A research poster and an oral presentation</li><li>A short technical paper or extended abstract</li><li>Reproducible code, notebooks, or a derivation package</li><li>A continuation plan for research, coursework, or your next career step</li></ul><p class="small">Research does not promise a predetermined positive outcome. Clear evidence, sound methods, and explicit limitations are central to a successful project.</p></div></section>'''+callout()
experience = experience.replace(callout(), f'''<section class="feature-section"><div class="container section"><div class="section-heading"><div>{label('Life beyond the project')}<h2>A summer of connections.</h2></div><p>Social activities bring the cohort together and connect you with the broader Illinois research community. These activities are planned; dates and visit details will be shared with participants.</p></div><div class="social-list">{''.join('<span>'+e(a)+'</span>' for a in D['social_activities'])}</div></div></section><section class="container section matching"><div>{label('Living at Illinois')}<h2>Room to focus.<br>Space to belong.</h2></div><div><h3>Housing, meals, and travel</h3><p>{e(D['housing_statement'])} Occasional meals are provided. Travel to and from campus is covered by the program.</p><h3>Accessible participation</h3><p>{e(D['accommodations_statement'])}</p>{link('mailto:'+D['contact_email'],'Discuss accommodations')}</div></section>'''+callout())
page('experience.html','The summer experience','The planned ten-week research pathway, mentoring, professional development, and student outcomes for Quantum REU 2027.',experience,'experience')

people=intro('Investigators & mentors','People who help<br>questions grow.','A research team spanning cryptography, quantum information, coding theory, and distributed computation—with shared support for your development as a researcher.')
people+='<section class="container people-list" aria-label="Faculty investigators and mentors">'
for m in D['mentors']:
 projectlinks=''.join(f'<a href="projects/{p["slug"]}.html">{p["id"]}</a>' for p in PROJECTS if p['id'] in m['projects'])
 people+=f'''<article class="person" id="{m['id']}"><div class="person-monogram" aria-hidden="true">{m['initials']}<span>{e(m['focus'])}</span></div><div class="person-body">{label(m['role'])}<h2>{e(m['name'])}</h2><p class="affiliation">{e(m['affiliation'])}</p><p>{e(m['bio'])}</p><div class="person-bottom">{link(m['url'],'Faculty / research profile')}<div class="project-links"><span>Project connections</span>{projectlinks}</div></div></div></article>'''
people+=f'''</section><section class="container section matching"><div>{label('A team around every student')}<h2>Support beyond<br>the research meeting.</h2></div><div><h3>Near-peer mentors</h3><p>Graduate students and postdoctoral researchers will support project work, scientific programming, and the day-to-day practice of research. Individual assignments will be shared with the cohort.</p><h3>Program coordination</h3><p>{e(D['contact_name'])} coordinates applicant communications and program logistics, including scheduling, housing, travel, and student-support arrangements.</p>{link('mailto:'+D['contact_email'],'Contact program coordination')}<p class="small">For research and program leadership questions: <a href="mailto:{e(D['pi_email'])}">Daniel Alabi</a>.</p></div></section>'''+callout()
page('people.html','Investigators and mentors','Meet Daniel Alabi, Eric Chitambar, Olgica Milenkovic, Milad Marvian, and the Quantum REU support team.',people,'people')

partners=intro('Partners & research environment','Connected to a wider<br>quantum community.','The program combines faculty-led research at Illinois with planned educational and workforce activities that connect students to the broader quantum ecosystem.')
partners+='''<section class="container section compact-top"><div class="section-heading"><div>'''+label('Educational & workforce partners')+'''<h2>Research in context.</h2></div><p>Partner roles below reflect the submitted program plan. The 2027 activity schedule and availability will be confirmed before the summer.</p></div><div class="partner-grid"><article class="partner-card"><div class="partner-wordmark">IBM <span>Quantum</span></div><h3>Quantum software & industry engagement</h3><p>Planned Qiskit-focused educational engagement will connect circuit construction, simulation, transpilation, execution workflows, and interpretation of results to student projects.</p><p>The program also plans to coordinate visitor access to IBM’s Chicago office. A possible educational visit associated with IBM Quantum System Two at Hyde Park Labs depends on installation, readiness, and visitor requirements; it is not guaranteed.</p><p class="small">The proposal identifies IBM Quantum Engagement Leader Tad Reese as an organizational contact.</p>'''+link('https://www.ibm.com/quantum','Explore IBM Quantum')+'''</article><article class="partner-card"><div class="partner-wordmark">Chicago Quantum<br><span>Exchange · Q-Ready</span></div><h3>Quantum careers & workforce development</h3><p>Planned connections to Q-Ready programming complement the research experience with technical skill building, employer spotlights, industry panels, and career conversations.</p><p>Activities will be selected to fit the cohort’s interests and the ten-week schedule. Students can connect these experiences to their Individual Development Plans and discuss next steps with their mentors.</p>'''+link('https://chicagoquantum.org/','Explore Chicago Quantum Exchange')+'''</article></div></section><section class="feature-section"><div class="container section"><div class="section-heading"><div>'''+label('The Illinois research environment')+'''<h2>A home for connected ideas.</h2></div></div><div class="resource-grid">'''
resources=[('Electrical & Computer Engineering','The host department connects the program to research in information, communication, security, and computation.','https://ece.illinois.edu/'),('IQUIST','The Illinois Quantum Information Science and Technology Center connects quantum researchers across campus disciplines.','https://iquist.illinois.edu/'),('Coordinated Science Laboratory','A campus setting for collaboration across communications, signal processing, quantum information, and cybersecurity.','https://csl.illinois.edu/'),('NCSA','The planned research environment includes campus computing resources for scientific simulation and reproducible computation.','https://www.ncsa.illinois.edu/'),('Office of Undergraduate Research','Campus research programming and support connect students to the broader undergraduate research community.','https://undergradresearch.illinois.edu/'),('Disability Resources & Educational Services','Participants can work with program coordination and campus resources to plan for accessible participation.','https://dres.illinois.edu/')]
partners+=''.join(f'<article><h3>{name}</h3><p>{desc}</p>{link(url,"Visit resource")}</article>' for name,desc,url in resources)
partners+='''</div></div></section><section class="container section matching"><div>'''+label('Learning from the program')+'''<h2>Feedback shapes<br>the experience.</h2></div><div><h3>CRA Center for Evaluating the Research Pipeline</h3><p>The submitted plan identifies CRA CERP for formative and summative program evaluation. Student feedback and research milestones will help the team improve mentoring and the program experience.</p><p class="small">Evaluation arrangements will be finalized as program support is confirmed. Partner participation does not imply financial sponsorship or an NSF award.</p>'''+link('https://cra.org/cerp/','Explore CRA CERP')+'''</div></section>'''+callout()
page('partners.html','Partners and research environment','Explore the Illinois research environment and planned educational partnerships with IBM Quantum and Chicago Quantum Exchange Q-Ready.',partners,'partners')

apply=intro('Join the 2027 cohort','A summer for<br>your next big question.',f'{D["students"]} undergraduate students. {D["weeks"]} weeks of mentored research. {e(D["dates"])} at the University of Illinois Urbana-Champaign.')
application_cta=link(D['application_url'],'Open the application','button') if D['application_url'] else link('mailto:'+D['contact_email']+'?subject=Quantum%20REU%202027%20inquiry','Ask about the program','button')
apply+=f'''<section class="container apply-layout"><div><div class="application-status">{label('Summer 2027')}<h2>{e(D['application_status'])}</h2><p>Application deadline: <strong>{e(D['application_deadline'])}</strong></p><p>The program will run regardless of the NSF funding decision. The application link will be posted here when applications open. Student support is confirmed: a $700 weekly stipend, fully covered housing and travel, and occasional meals.</p>{application_cta}<a class="calendar-link" href="assets/quantum-reu-2027.ics" download>Add program dates to your calendar <span aria-hidden="true">↓</span></a></div><section class="apply-section"><h2>Who should consider the program?</h2><p>Undergraduates in computer science, electrical and computer engineering, physics, mathematics, statistics, and related fields who want to explore quantum-network research.</p><p>Preparation in at least one area—programming, linear algebra, probability, discrete mathematics, algorithms, circuits, signals, or modern physics—can provide an entry point. Prior quantum coursework is not required.</p><p>Students with limited access to research at their home institutions are especially encouraged to explore the program. Preparation and potential are considered in context.</p></section><section class="apply-section"><h2>Start thinking about your interests</h2><p>The proposed application process includes the items below. Final requirements will be published when applications open.</p><ul class="outcome-list"><li>A research-interest statement identifying one or more thrusts</li><li>An unofficial transcript and a preparation inventory, including coursework, projects, employment, or self-study</li><li>A description of prior research access, anticipated benefit, and next steps</li><li>One recommendation addressing learning habits, persistence, initiative, and collaboration</li></ul><p>The proposed review is holistic, with no strict GPA cutoff and no application fee.</p>{link('projects.html','Explore projects before you apply')}</section></div><aside class="apply-sidebar"><section><h2>Program at a glance</h2><dl><dt>Dates</dt><dd>{e(D['dates'])}</dd><dt>Length</dt><dd>{D['weeks']} weeks · Full-time summer research</dd><dt>Cohort</dt><dd>{D['students']} undergraduate students</dd><dt>Location</dt><dd>{e(D['location'])}</dd><dt>Format</dt><dd>Residential program</dd></dl></section><section><h2>Student support</h2><p>{e(D['support_statement'])}</p></section><section><h2>Eligibility</h2><p>{e(D['eligibility_statement'])}</p></section><section><h2>Questions & accessibility</h2><p>For application questions, program logistics, or accommodation planning, contact {e(D['contact_name'])}.</p><a class="email-link" href="mailto:{e(D['contact_email'])}">{e(D['contact_email'])}</a></section></aside></section><section class="container section faq" id="faq">{label('Frequently asked questions')}<h2>A few things to know.</h2>'''
faqs=[('Will the program happen if NSF does not fund the proposal?','Yes. The PI has confirmed the ten-week program for 10 students, May 24–July 30, 2027, regardless of the NSF decision. The program includes a $700 weekly stipend, fully covered on-campus housing and travel, and occasional meals.'),('Do I need quantum computing experience?','No prior quantum coursework is required. Bridge modules and the first-week bootcamp introduce shared foundations. Different backgrounds offer different entry points into the research.'),('Can I participate remotely or for part of the summer?','The program is planned as a full-time, ten-week residential experience at Illinois. Contact program coordination to discuss individual circumstances; alternative arrangements are not advertised as available.'),('Can I choose my project?','You can indicate preferred thrusts and interests. Matching considers preparation, mentor capacity, and cohort balance. The final research question and scope will be developed with your mentor.'),('Will I work on a quantum computer?','Many projects use theory and classical simulation. Some may use Qiskit or a quantum platform, but specialized hardware access is not required for every project and is not guaranteed.'),('Are international students eligible?',D['eligibility_statement']),('What financial support is available?',D['support_statement']),('How can I apply?',('Use the application link above. Check the published application for final requirements.' if D['application_url'] else 'Applications open December 1, 2026. The planned deadline is January 30, 2027. The application link will appear here when the application opens; contact program coordination with questions.'))]
apply+=''.join(f'<details><summary>{e(q)}<span aria-hidden="true">+</span></summary><p>{e(a)}</p></details>' for q,a in faqs)+'</section>'
timeline_rows = ''.join(f'<li><strong>{e(item["date"])}</strong><span>{e(item["event"])}{" <em>(planned)</em>" if not item["confirmed"] else ""}</span></li>' for item in D['application_timeline'])
timeline_html = f'<div class="application-timeline"><h3>Application timeline</h3><ul>{timeline_rows}</ul><p class="small">Planned review dates follow the prior Illinois Physics REU cycle, adapted to 2027. Application opening and program dates are confirmed. Office hours and arrival arrangements will be announced separately. <a href="https://physics.illinois.edu/research/reu">Timeline reference</a>.</p></div>'
apply = apply.replace('</div><section class="apply-section">', timeline_html+'</div><section class="apply-section">', 1)
apply = apply.replace('<section><h2>Eligibility</h2>', f'<section><h2>Housing &amp; accessibility</h2><p>{e(D["housing_statement"])}</p><p>{e(D["accommodations_statement"])}</p></section><section><h2>Eligibility</h2>')
page('apply.html','Participation and applications','2027 dates, participation details, application status, preparation, support, eligibility, and frequently asked questions.',apply,'apply')
